css:
.cd{
  font-family: -apple-system, "Segoe UI", Roboto, sans-serif;
  padding: 16px;
  max-width: 1200px;
  margin: 0 auto;
  color: #14311d;
}
.navbar{display:none;}
.web-footer{display:none;}
.cd-top{
  display:flex;
  flex-wrap:wrap;
  gap:14px;
  align-items:center;
  justify-content:space-between;
  margin-bottom:18px;
}

.cd-title{
  font-size:20px;
  font-weight:700;
}

.cd-sub{
  font-size:13px;
  color:#5c7a68;
  margin-top:2px;
}

.cd-controls{
  display:flex;
  flex-wrap:wrap;
  gap:8px;
  align-items:center;
}

.cd-select,
.cd-date{
  border:1px solid #d3e3d8;
  border-radius:10px;
  padding:7px 10px;
  font-size:13px;
  background:#fff;
}

.cd-btn{
  background:linear-gradient(135deg,#1b5e20,#2e7d32);
  color:#fff;
  border:none;
  border-radius:10px;
  padding:8px 16px;
  font-size:13px;
  font-weight:600;
  cursor:pointer;
}

.cd-btn:hover{
  filter:brightness(1.08);
}

.cd-cards{
  display:grid;
  grid-template-columns:repeat(4,1fr);
  gap:12px;
  margin-bottom:20px;
}

.cd-card{
  background:linear-gradient(165deg,rgba(255,255,255,.95),rgba(236,248,238,.85));
  border:1px solid rgba(27,94,32,.12);
  border-radius:14px;
  padding:14px 16px;
  box-shadow:0 6px 18px rgba(15,61,30,.08);
}

.cd-card .k{
  font-size:12px;
  color:#5c7a68;
  margin-bottom:6px;
}

.cd-card .v{
  font-size:20px;
  font-weight:700;
  color:#14311d;
}

.cd-table-wrap{
  overflow-x:auto;
  border-radius:14px;
  border:1px solid rgba(27,94,32,.12);
  background:#fff;
}

.cd-table{
  width:100%;
  border-collapse:collapse;
  font-size:13px;
  min-width:520px;
}

.cd-table th{
  text-align:left;
  padding:11px 14px;
  background:#eef6f0;
  color:#1b5e20;
  font-weight:700;
  position:sticky;
  top:0;
}

.cd-table td{
  padding:10px 14px;
  border-top:1px solid #eef2ee;
}

.cd-table tr:hover td{
  background:#f7fbf8;
}

.cd-empty{
  text-align:center;
  color:#8aa596;
  padding:26px !important;
}

/* ================= RESPONSIVE ================= */

@media(max-width:900px){
  .cd-cards{
    grid-template-columns:repeat(2,1fr);
  }
}

@media(max-width:640px){
  .cd{
    padding:10px;
  }

  .cd-top{
    flex-direction:column;
    align-items:stretch;
  }

  .cd-controls{
    flex-direction:column;
    align-items:stretch;
  }

  .cd-controls > *{
    width:100%;
  }

  .cd-cards{
    grid-template-columns:1fr 1fr;
    gap:8px;
  }

  .cd-card{
    padding:11px 12px;
  }

  .cd-card .v{
    font-size:17px;
  }

  .cd-table{
    min-width:0;
    font-size:12px;
  }

  .cd-table th,
  .cd-table td{
    padding:8px 8px;
  }
}

javascript:
(function(){

  function inr(n){
    n = Number(n || 0);
    return "₹" + n.toLocaleString("en-IN", {maximumFractionDigits:0});
  }

  function firstDayOfMonth(){
    var d = new Date();
    return new Date(d.getFullYear(), d.getMonth(), 1)
      .toISOString().slice(0,10);
  }

  function today(){
    return new Date().toISOString().slice(0,10);
  }

  window.cdLoad = function(){

    var fromEl = document.getElementById("cdFrom");
    var toEl = document.getElementById("cdTo");
    var selEl = document.getElementById("cdClusterSel");

    if(!fromEl.value){ fromEl.value = firstDayOfMonth(); }
    if(!toEl.value){ toEl.value = today(); }

    var qs = "from_date=" + encodeURIComponent(fromEl.value) +
              "&to_date=" + encodeURIComponent(toEl.value);

    if(selEl && selEl.value){
      qs += "&cluster=" + encodeURIComponent(selEl.value);
    }

    document.getElementById("cdSub").textContent = "Loading…";

    fetch("/api/method/cluster_dashboard_api?" + qs)
      .then(function(r){ return r.json(); })
      .then(function(j){

        var data = j.message || {};

        document.getElementById("cdTitle").textContent =
          data.cluster || "Cluster Dashboard";

        document.getElementById("cdSub").textContent =
          (data.from_date || "") + " → " + (data.to_date || "") +
          " · " + (data.branches ? data.branches.length : 0) + " branches";

        // cluster selector (only shown if more than one cluster configured)
        if(selEl){
          if(data.available_clusters && data.available_clusters.length > 1){
            selEl.style.display = "";
            if(!selEl.dataset.filled){
              var opts = "<option value=''>My Cluster</option>";
              opts += "<option value='ALL'>All Branches</option>";
              data.available_clusters.forEach(function(c){
                opts += "<option value='" + c + "'>" + c + "</option>";
              });
              selEl.innerHTML = opts;
              selEl.dataset.filled = "1";
            }
          }else{
            selEl.style.display = "none";
          }
        }

        var t = data.totals || {};

        document.getElementById("cdCards").innerHTML =
          "<div class='cd-card'><div class='k'>Sales</div><div class='v'>" + inr(t.sales_amt) + "</div></div>" +
          "<div class='cd-card'><div class='k'>Invoices</div><div class='v'>" + (t.sales_count || 0) + "</div></div>" +
          "<div class='cd-card'><div class='k'>Collections</div><div class='v'>" + inr(t.collections) + "</div></div>" +
          "<div class='cd-card'><div class='k'>Outstanding</div><div class='v'>" + inr(t.outstanding) + "</div></div>";

        var rows = data.rows || [];
        var tbody = document.getElementById("cdTbody");

        if(!rows.length){
          tbody.innerHTML = "<tr><td colspan='5' class='cd-empty'>No branches configured for this cluster yet.</td></tr>";
          return;
        }

        tbody.innerHTML = rows.map(function(r){
          return "<tr>" +
            "<td>" + r.branch + "</td>" +
            "<td>" + inr(r.sales_amt) + "</td>" +
            "<td>" + r.sales_count + "</td>" +
            "<td>" + inr(r.collections) + "</td>" +
            "<td>" + inr(r.outstanding) + "</td>" +
            "</tr>";
        }).join("");

      })
      .catch(function(e){
        document.getElementById("cdSub").textContent = "Failed to load data.";
        void 0;
      });

  };

  document.addEventListener("DOMContentLoaded", function(){
    cdLoad();
  });

  // in case the block loads after DOMContentLoaded already fired
  if(document.readyState !== "loading"){
    cdLoad();
  }

})();
